CREATE OR REPLACE FUNCTION propiedad_${llaveTabla}(documento character varying) RETURNS SETOF pedidoventacaracteristica_pvcp AS
$BODY$
${valor}
$BODY$ 
LANGUAGE plpgsql VOLATILE
COST 100;

select cppd_llave as llaveTabla ,cppd_propiedadvalor as propiedadValor ,cppd_tipo as tipo ,cpvd_nombre as nombre ,cpvd_codigo as key ,cppd_campo as campo ,case when bpvd_privada = true then 'private' else cppd_valor endcppd_valor as valor ,cppd_texto as texto ,cppd_rol as rol ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave =(select crac_plantilla from rolacceso_racp where crac_llave = cppd_rol)) as rolNombre ,cppd_rolexcluyente as rolExcluyente ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave =(select crac_plantilla from rolacceso_racp where crac_llave = cppd_rolexcluyente)) as rolExcluyenteNombre ,dppd_fechainicial as fechaInicial ,dppd_fechafinal as fechaFinal ,cppd_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cppd_usuario) as usuarioNombre ,cppd_usuarioexcluyente as usuarioExcluyente ,(select cusr_nombre from usuario_usrp where cusr_llave = cppd_usuarioexcluyente) as usuarioExcluyenteNombre ,cppd_motivo as motivo ,cppd_estado as estado from propiedad_ppdp a inner join propiedadvalordefinido_pvdp on (cpvd_llave = cppd_propiedadvalor) where cppd_estado = 'A' and cppd_tipo = #{dto.tipo} and cppd_campo = #{dto.campo} and cppd_propiedadvalor = #{dto.propiedadValor}
and (cppd_rol is null or cppd_rol in (select cerl_rolacceso from usuariorol_erlp where cerl_estado = 'A' and cerl_usuario = #{usuario})) and (cppd_rolExcluyente is null or cppd_rolExcluyente in (select cerl_rolacceso from usuariorol_erlp where cerl_estado = 'A' and cerl_usuario = #{usuario})) and (cppd_usuario is null or cppd_usuario = #{usuario}) and (cppd_usuarioExcluyente is null or cppd_usuarioExcluyente = #{usuario}) and (dppd_fechainicial is null or dppd_fechainicial < #{fecha}) and (dppd_fechafinal is null or dppd_fechafinal > #{fecha})
and (upper(cppd_codigo) like upper('%' || #{dto.filtroParametro} || '%')) order by nombre, key, fechainicial, dppd_fechafinal , usuario, rol, texto, valor
